def _benchmark_algorithms(messages: list) -> Dict[str, Dict]:
    """Benchmark különböző algoritmusokkal."""
    results = {}

    for algo_name, algo in [
        ("NONE", CompressionAlgorithm.NONE),
        ("GZIP-1", CompressionAlgorithm.GZIP),  # will use level from compressor
        ("ZLIB", CompressionAlgorithm.ZLIB),
    ] + ([("LZ4", CompressionAlgorithm.LZ4)] if LZ4_AVAILABLE else []):
        comp = PayloadCompressor(
            default_algo=algo,
            compression_level=6 if algo != CompressionAlgorithm.LZ4 else 6,
        )
        total_orig = 0
        total_comp = 0
        total_ctime = 0
        total_dtime = 0

        for msg in messages:
            raw = json.dumps(msg, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            total_orig += len(raw)

            t0 = time.perf_counter()
            compressed = comp.compress_message(msg, algo=algo if algo != CompressionAlgorithm.NONE else CompressionAlgorithm.NONE)
            t1 = time.perf_counter()
            total_ctime += t1 - t0

            _, _, orig_s, comp_s, _ = struct.unpack(HEADER_FORMAT, compressed[:HEADER_SIZE])
            total_comp += comp_s

            t2 = time.perf_counter()
            _ = comp.decompress_message(compressed)
            t3 = time.perf_counter()
            total_dtime += t3 - t2

        ratio = total_comp / total_orig if total_orig > 0 else 0
        results[algo_name] = {
            "original_bytes": total_orig,
            "compressed_bytes": total_comp,
            "ratio": ratio,
            "savings": 1 - ratio,
            "compress_ms": total_ctime * 1000,
            "decompress_ms": total_dtime * 1000,
        }

    return results


def main():
    """Demo és benchmark futtatás."""
    print("=" * 60)
    print("A2A Mesh — P2P Payload Compression Demo")
    print("Generated by runa via A2A Mesh delegation")
    print("=" * 60)

    # Sample üzenetek generálása
    messages = _generate_sample_a2a_messages()
    print(f"\nGenerated {len(messages)} sample A2A Mesh messages")

    # Transport demo
    transport = P2PCompressedTransport(
        algo=CompressionAlgorithm.GZIP,
        level=6,
    )

    print("\n--- Round-trip Test ---")
    for i, msg in enumerate(messages):
        compressed = transport.send(msg)
        decompressed = transport.receive(compressed)
        assert decompressed == msg, f"Round-trip failed for message {i}!"
        orig_json = json.dumps(msg, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        _, _, orig_size, comp_size, _ = struct.unpack(
            HEADER_FORMAT, compressed[:HEADER_SIZE]
        )
        savings = 1 - (comp_size / orig_size) if orig_size > 0 else 0
        print(
            f"  Message {i+1} ({msg['type']:20s}): "
            f"{orig_size:>7,} -> {comp_size:>7,} bytes "
            f"({savings:>5.1%} savings) ✓"
        )

    print(transport.stats_report())

    # Benchmark
    print("\n--- Algorithm Benchmark ---")
    results = _benchmark_algorithms(messages)

    print(f"\n{'Algorithm':<12} {'Original':>12} {'Compressed':>12} {'Savings':>10} {'Cmp(ms)':>10} {'Dcmp(ms)':>10}")
    print("-" * 70)
    for name, r in results.items():
        print(
            f"{name:<12} {r['original_bytes']:>12,} {r['compressed_bytes']:>12,} "
            f"{r['savings']:>9.1%} {r['compress_ms']:>9.2f} {r['decompress_ms']:>9.2f}"
        )

    # Envelope demo
    print("\n--- Envelope Demo ---")
    env = CompressedMessageEnvelope()
    test_msg = messages[0]
    wrapped = env.wrap(test_msg)
    print(f"  Original message size: {len(json.dumps(test_msg)):,} bytes")
    print(f"  Envelope payload size: {wrapped['payload_size']:,} bytes")
    print(f"  Algorithm: {wrapped['algorithm']}")
    print(f"  Savings: {1 - wrapped['payload_size']/wrapped['original_size']:.1%}")

    unwrapped = env.unwrap(wrapped)
    assert unwrapped == test_msg, "Envelope round-trip failed!"
    print("  Round-trip: ✓")

    # Stress test — sok üzenet
    print("\n--- Stress Test (1000 messages) ---")
    stress_transport = P2PCompressedTransport()
    stress_msgs = messages * 200  # 1000 üzenet
    t0 = time.perf_counter()
    for msg in stress_msgs:
        compressed = stress_transport.send(msg)
        _ = stress_transport.receive(compressed)
    elapsed = time.perf_counter() - t0
    print(f"  1000 messages compressed + decompressed in {elapsed:.3f}s")
    print(f"  Throughput: {1000/elapsed:.0f} msg/s")
    print(stress_transport.stats_report())

    print("\n✓ All tests passed!")


